import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, DoubleSide } = ctx.THREE;

  // Root object for this node
  const root = new Group();

  // Plane geometry – use image aspect ratio if available
  const aspect = 512 / 320; // fallback aspect from atlas region
  const width = aspect;
  const height = 1;
  const geometry = new PlaneGeometry(width, height);

  // Basic material; texture will be assigned asynchronously
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    map: null,
    side: DoubleSide,
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load the brushed‑metal texture
  let loadedTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTex = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // No interactive handlers for this node
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose of GSAP timelines if any (none in this node)
    // Dispose material, geometry and texture
    if (material) material.dispose();
    if (geometry) geometry.dispose();
    if (loadedTex) loadedTex.dispose();
  };

  return root;
}
